const panel=document.createElement('section');panel.className='live-connection';panel.innerHTML=`<div class="panel-title"><strong>پنل مدیریت لدو لایو</strong><button id="hidePanel">بستن پنل و نمایش لایو</button></div><p id="liveStatus" role="status">در حال دریافت وضعیت…</p><div id="authBox" class="map-row"><input id="adminKey" type="password" placeholder="کلید مدیریت" aria-label="کلید مدیریت"><button id="unlock">ورود به پنل</button></div><div id="adminTools" hidden><div class="map-row"><input id="liveUsername" placeholder="نام حساب تیک‌تاک بدون @" aria-label="نام حساب تیک‌تاک"><button id="connectLive">اتصال به لایو</button><button id="disconnectLive">قطع و حالت آزمایشی</button></div><div id="giftMappings"></div><p id="lastLiveGift" class="muted"></p><div class="map-row"><button id="demo0">آزمایش گوشه ۱</button><button id="demo1">آزمایش گوشه ۲</button><button id="demo2">آزمایش گوشه ۳</button><button id="demo3">آزمایش گوشه ۴</button></div><p>چهار گیفت از پیش تنظیم‌اند. هر کشور پس از دو نوبت کامل خودش بدون هیچ گیفتی، خودکار با کشور اول صف عوض می‌شود. تعداد کل گیفت حامی، رتبهٔ او را تعیین می‌کند؛ روی فریم برای دیدن همهٔ حامیان کلیک کنید.</p><details><summary>درخواست کشورها با کامنت</summary><p>هر بیننده یک انتخاب فعال دارد؛ با کامنت شمارهٔ کشور دیگر، یک درخواست از قبلی کم و به جدید اضافه می‌شود. اعداد انگلیسی، فارسی و عربی پذیرفته می‌شوند. شمارهٔ کشور با تغییر رتبه عوض نمی‌شود.</p><div class="map-row"><input id="demoComment" placeholder="شمارهٔ کشور" inputmode="numeric"><input id="demoViewer" placeholder="شناسهٔ بیننده آزمایشی" value="viewer-1"><button id="sendDemoComment">آزمایش کامنت</button></div><div id="queueAdmin"></div></details></div>`;
document.querySelector('main').prepend(panel);const toggle=document.createElement('button');toggle.className='panel-toggle';toggle.textContent='⚙ Settings';toggle.onclick=()=>{document.body.classList.remove('broadcast');panel.scrollIntoView({behavior:'smooth'})};document.body.append(toggle);
const originalRender=render;render=function(){originalRender();drawProfiles();animateMove();if(openSupporterCorner!==null&&$('supporterDialog').open)renderSupporters(openSupporterCorner)};
function makeAvatar(container,person){container.textContent=person?Array.from(person.name||'?')[0]:'♙';if(person?.avatar&&/^https:\/\//.test(person.avatar)){const img=document.createElement('img');img.src=person.avatar;img.alt=person.name||'Supporter';img.referrerPolicy='no-referrer';img.addEventListener('error',()=>img.remove(),{once:true});container.append(img)}}
function giftLabel(i){const preset=oneCoinGifts.find(g=>g.id===giftMap[i]);return preset?{symbol:preset.symbol,name:preset.name}:{symbol:'🎁',name:state.teams[i].gift||'Gift'}}
function drawProfiles(){document.querySelectorAll('.player-frame').forEach(e=>e.remove());const positions=['top-left','top-right','bottom-right','bottom-left'];state.teams.forEach((t,i)=>{const frame=document.createElement('button');frame.type='button';frame.className='player-frame '+positions[i];frame.style.setProperty('--team-color',colors[i]);frame.id='player-frame-'+i;frame.setAttribute('aria-label',t.name+' supporters');frame.onclick=()=>showSupporters(i);const face=document.createElement('div');face.className='profile-face';makeAvatar(face,t.supporter);if(t.supporter){const crown=document.createElement('span');crown.className='leader-crown';crown.textContent='♛';face.append(crown)}const country=document.createElement('div');country.className='player-country';country.textContent=(rosterMode==='countries'?t.flag+' ':'')+t.name;if(rosterMode==='teams'&&t.teamAvatar){const badge=document.createElement('img');badge.src=t.teamAvatar;badge.alt=t.name;badge.className='team-badge';country.prepend(badge)}const name=document.createElement('div');name.className='player-name';name.textContent=t.active===false?'ELIMINATED':t.supporter?.name||'YOUR PROFILE HERE';const gift=document.createElement('div');gift.className='player-gift';const icon=document.createElement('span');icon.className='gift-symbol';icon.textContent=giftLabel(i).symbol;const label=document.createElement('span');label.textContent=giftLabel(i).name+' · '+t.g;gift.append(icon,label);const comment=document.createElement('span');comment.className='play-code';comment.textContent=inputMode==='gifts'?'1 COIN GIFT':'COMMENT '+(i+1);frame.append(comment);const total=document.createElement('span');total.className='supporter-total';if(t.g>0)total.textContent=(t.supporters?.length||1)+' SUPPORTERS · TOP '+(t.supporter?.gifts||0);else{total.textContent=(inputMode==='gifts'?'NO GIFTS · '+(t.noGiftTurns||0)+'/2 TURNS':'FREE TO PLAY');if(t.noGiftTurns)total.classList.add('elimination-warning')}frame.append(face,country,name,total,gift);document.querySelector('.board-wrap').append(frame)});
const mapping=$('giftMappings');if(!mapping.contains(document.activeElement)){mapping.replaceChildren();state.teams.forEach((t,i)=>{const row=document.createElement('label');row.className='map-row';const label=document.createElement('span');label.className='map-label';label.textContent=t.flag+' '+t.name+' · '+giftLabel(i).symbol+' '+giftLabel(i).name;const input=document.createElement('select');input.id='giftId'+i;input.setAttribute('aria-label',t.name+' one coin gift');oneCoinGifts.forEach(g=>{const option=document.createElement('option');option.value=g.id;option.textContent=g.symbol+' '+g.name+' · 1 coin';option.disabled=giftMap.some((id,j)=>j!==i&&id===g.id);input.append(option)});input.value=giftMap[i]||'';input.onchange=()=>{const value=input.value.trim();if(!oneCoinGifts.some(g=>g.id===value)||giftMap.some((v,j)=>j!==i&&v===value)){message('Every country needs a unique numeric gift ID.');input.value=giftMap[i]||'';return}giftMap[i]=value;const p=oneCoinGifts.find(p=>p.id===value);if(p)state.teams[i].gift=p.symbol+' '+p.name;queueSync()};row.append(label,input);mapping.append(row)})}
$('queueAdmin').replaceChildren();state.queue.forEach(t=>{const row=document.createElement('div');row.className='queue-admin map-row';const label=document.createElement('span');label.className='request-label';label.textContent=t.requestId+' · '+t.flag+' '+t.name+' ('+(t.requests||0)+')';const minus=document.createElement('button'),plus=document.createElement('button');minus.textContent='−';plus.textContent='+';minus.onclick=()=>command('queue-adjust',{requestId:t.requestId,delta:-1});plus.onclick=()=>command('queue-adjust',{requestId:t.requestId,delta:1});row.append(label,minus,plus);$('queueAdmin').append(row)})}
function renderSupporters(i){const t=state.teams[i];$('supporterTitle').textContent=(rosterMode==='countries'?t.flag+' ':'')+t.name;$('supporterList').replaceChildren();const list=[...(t.supporters||[])].sort((a,b)=>b.gifts-a.gifts||a.at-b.at);if(!list.length){const empty=document.createElement('p');empty.className='muted';empty.textContent='No gifts yet. Be the first to support '+t.name+'.';$('supporterList').append(empty)}list.forEach((donor,rank)=>{const row=document.createElement('div');row.className='supporter-row';const pos=document.createElement('span');pos.className='supporter-rank';pos.textContent=rank===0?'♛':String(rank+1);const avatar=document.createElement('div');avatar.className='supporter-avatar';makeAvatar(avatar,donor);const info=document.createElement('div');const name=document.createElement('strong');name.textContent=donor.name;const tag=document.createElement('small');tag.textContent=rank===0?'TOP SUPPORTER':'COUNTRY SUPPORTER';info.append(name,tag);const score=document.createElement('span');score.className='supporter-score';score.textContent=String(donor.gifts);const unit=document.createElement('small');unit.textContent=donor.gifts===1?'gift':'gifts';score.append(unit);row.append(pos,avatar,info,score);$('supporterList').append(row)})}
function showSupporters(i){openSupporterCorner=i;renderSupporters(i);if(!$('supporterDialog').open)$('supporterDialog').showModal()}
$('closeSupporters').onclick=()=>{$('supporterDialog').close();openSupporterCorner=null};$('supporterDialog').addEventListener('close',()=>openSupporterCorner=null);$('supporterDialog').addEventListener('click',e=>{if(e.target===$('supporterDialog')){$('supporterDialog').close();openSupporterCorner=null}});
const originalPersist=persist;persist=function(){originalPersist();queueSync()};
function collect(){return{schemaVersion:5,rosterMode,inputMode,state,config,giftMap,likes:likeCount,fans,display:{portrait:document.body.classList.contains('portrait'),bg:localStorage.getItem('ludo-bg')||'#070b21',width:localStorage.getItem('ludo-width')||100,volume:Number($('volume').value),effects:$('effects').checked,sound:$('sound').checked}}}
function queueSync(){if(applyingRemote||!admin||!ready)return;clearTimeout(syncTimer);syncTimer=setTimeout(()=>{if(socket?.readyState===1){const next=collect(),key=JSON.stringify(next);if(key!==lastSynced){lastSynced=key;socket.send(JSON.stringify({type:'update',revision:serverRevision,snapshot:next}))}}},100)}
function remote(m){applyingRemote=true;serverRevision=m.revision;const s=m.snapshot;rosterMode=s.rosterMode||'countries';inputMode=s.inputMode||'comments';state=s.state;config=s.config;giftMap=s.giftMap;likeCount=s.likes||0;fans=s.fans||[];render();$('likes').textContent=new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(likeCount);const d=s.display||{};$('effects').checked=d.effects!==false;$('sound').checked=!!d.sound;$('volume').value=d.volume??20;document.body.classList.toggle('portrait',d.portrait!==false);updateModeLabels();renderRosterEditor();if(d.bg){document.body.style.setProperty('--backdrop',d.bg);localStorage.setItem('ludo-bg',d.bg)}document.querySelector('main').style.maxWidth=(Number(d.width||100)*14.4)+'px';$('liveStatus').textContent=m.status;$('liveUsername').placeholder=m.username?'@'+m.username:'نام حساب تیک‌تاک بدون @';ready=true;lastSynced=JSON.stringify(collect());applyingRemote=false}
function command(type,rest={}){if(socket?.readyState===1)socket.send(JSON.stringify({type,...rest}));else message('Connection lost. Reconnecting…')}
function authenticate(){const key=$('adminKey').value.trim()||sessionStorage.getItem('ludo-admin')||decodeURIComponent(location.hash.slice(1));if(key)command('auth',{token:key})}
function openSocket(){clearTimeout(retryTimer);socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/events');socket.onopen=authenticate;socket.onmessage=event=>{try{const m=JSON.parse(event.data);if(m.type==='snapshot')remote(m);else if(m.type==='auth'){admin=m.ok;document.body.classList.toggle('can-manage',admin);$('authBox').hidden=admin;$('adminTools').hidden=!admin;if(admin){const key=$('adminKey').value.trim()||sessionStorage.getItem('ludo-admin')||decodeURIComponent(location.hash.slice(1));sessionStorage.setItem('ludo-admin',key);$('adminKey').value='';message('Management panel ready. Gifts and countries are preconfigured.')}else message('Invalid management key.')}else if(m.type==='effect'){effect(m.symbol);if(Number.isInteger(m.corner))$('player-frame-'+m.corner)?.classList.add('new-gift')}else if(m.type==='last-gift')$('lastLiveGift').textContent='آخرین گیفت: '+m.giftName+' · ID '+m.giftId;else if(m.type==='notice'||m.type==='error')message(m.message)}catch(error){console.warn('Live update failed:',error.message)}};socket.onclose=()=>{admin=false;document.body.classList.remove('can-manage');$('liveStatus').textContent='ارتباط سرور قطع شد؛ تلاش مجدد…';retryTimer=setTimeout(openSocket,3000)}}
$('unlock').onclick=authenticate;$('hidePanel').onclick=()=>{document.body.classList.add('broadcast');window.scrollTo?.({top:0,behavior:'smooth'})};$('connectLive').onclick=()=>command('connect',{username:$('liveUsername').value.trim()});$('disconnectLive').onclick=()=>command('disconnect');for(let i=0;i<4;i++)$('demo'+i).onclick=()=>command('demo-gift',{corner:i});$('sendDemoComment').onclick=()=>command('demo-comment',{content:$('demoComment').value.trim(),userId:$('demoViewer').value.trim()||'viewer-1'});document.addEventListener('change',queueSync);document.addEventListener('click',()=>{if(admin)setTimeout(queueSync,0)});drawProfiles();openSocket();if(location.pathname==='/screen')document.body.classList.add('broadcast');

// Public labels stay English; the owner controls can remain Persian.
const rosterTools=document.createElement('details');rosterTools.id='rosterTools';rosterTools.innerHTML=`<summary>کشورها، تیم‌ها و عکس شرکت‌کننده‌ها</summary><div class="map-row"><label>حالت صفحه <select id="rosterMode"><option value="countries">کشورها · Countries</option><option value="teams">تیم / افراد · Teams</option></select></label><label>روش حرکت <select id="inputMode"><option value="comments">کامنت رایگان · Free comments</option><option value="gifts">گیفت یک‌کوینی · Gifts</option><option value="both">کامنت و گیفت · Both</option></select></label></div><p>کامنت‌های 1 تا 4 مهره‌های داخل میدان را حرکت می‌دهند. درخواست ورود تیم‌های منتظر با شماره‌های 5 تا 14 است. در حالت کامنت، هیچ پرداختی لازم نیست و قانون حذف بدون گیفت غیرفعال است.</p><div class="map-row"><select id="rosterEntry" aria-label="انتخاب تیم"></select><input id="rosterName" placeholder="English team or person name" maxlength="32" aria-label="Team name"><input id="rosterFlag" placeholder="🇦🇫" aria-label="Flag" maxlength="12"></div><div class="map-row"><label>عکس فرد / تیم <input id="rosterPhoto" type="file" accept="image/jpeg,image/png,image/webp"></label><button id="saveRoster">ذخیره نام و عکس</button><button id="clearRosterPhoto">حذف عکس</button></div><img id="rosterPreview" class="roster-preview" alt="Team picture preview" hidden><p>نام نمایشی را انگلیسی وارد کنید. عکس تیم جای بیرق می‌آید؛ عکس بزرگ داخل فریم همچنان حامی برتر است. گیفت هر گوشه حداکثر ۱ کوین و مستقل از کشور یا تیم جایگزین است.</p>`;
$('adminTools').prepend(rosterTools);let draftPhoto=undefined;
function selectedEntry(){const [kind,key]=$('rosterEntry').value.split(':');return kind==='active'?state.teams[Number(key)]:state.queue.find(t=>t.requestId===Number(key))}
function fillRosterDraft(){const t=selectedEntry();if(!t)return;draftPhoto=undefined;$('rosterName').value=t.name;$('rosterFlag').value=t.flag||'';$('rosterPhoto').value='';$('rosterPreview').hidden=!t.teamAvatar;if(t.teamAvatar)$('rosterPreview').src=t.teamAvatar}
function renderRosterEditor(){if(!$('rosterEntry'))return;const select=$('rosterEntry'),prior=select.value;if(rosterTools.contains(document.activeElement))return;select.replaceChildren();state.teams.forEach((t,i)=>{const o=document.createElement('option');o.value='active:'+i;o.textContent='IN GAME '+(i+1)+' · '+t.name;select.append(o)});state.queue.forEach(t=>{const o=document.createElement('option');o.value='queue:'+t.requestId;o.textContent='WAITING '+t.requestId+' · '+t.name;select.append(o)});if([...select.options].some(o=>o.value===prior))select.value=prior;if(!prior||!selectedEntry())fillRosterDraft();$('rosterMode').value=rosterMode;$('inputMode').value=inputMode}
$('rosterEntry').onchange=fillRosterDraft;$('rosterMode').onchange=()=>{rosterMode=$('rosterMode').value;render();updateModeLabels();queueSync()};$('inputMode').onchange=()=>{inputMode=$('inputMode').value;render();updateModeLabels();queueSync()};
$('rosterPhoto').onchange=async()=>{const file=$('rosterPhoto').files[0];if(!file)return;if(file.size>5*1024*1024){message('Choose an image smaller than 5 MB.');return}try{const img=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=160;canvas.height=160;const ctx=canvas.getContext('2d');const side=Math.min(img.width,img.height);ctx.drawImage(img,(img.width-side)/2,(img.height-side)/2,side,side,0,0,160,160);draftPhoto=canvas.toDataURL('image/webp',.75);img.close();if(draftPhoto.length>40000){message('Image is too large. Choose a simpler image.');draftPhoto=undefined;return}$('rosterPreview').src=draftPhoto;$('rosterPreview').hidden=false}catch{message('This image could not be opened. Use JPG, PNG or WebP.')}};
$('clearRosterPhoto').onclick=()=>{draftPhoto='';$('rosterPreview').hidden=true};$('saveRoster').onclick=()=>{const t=selectedEntry(),name=$('rosterName').value.trim();if(!t)return;if(!name||/[^\x20-\x7E]/.test(name)){message('Enter an English display name.');return}t.name=name;t.flag=$('rosterFlag').value.trim()||'🏳';if(draftPhoto!==undefined)t.teamAvatar=draftPhoto;config=state.teams.map(t=>[t.flag,t.name,t.gift].join('|')).concat(state.queue.slice().sort((a,b)=>a.requestId-b.requestId).map(t=>[t.flag,t.name].join('|'))).join('\n');draftPhoto=undefined;render();queueSync();message('Team name and picture saved.');fillRosterDraft()};
function updateModeLabels(){const team=rosterMode==='teams';const heading=document.querySelector('.live-heading h1');heading.textContent=team?'Back your team.':'Raise your flag.';document.querySelector('.live-heading .eyebrow').textContent=team?'FOUR TEAMS. ONE ARENA.':'FOUR COUNTRIES. ONE ARENA.';document.querySelector('.live-heading p').textContent=inputMode==='gifts'?'Send a 1-coin gift. Support your favorite.':'Play for free. Comment 1, 2, 3 or 4 to move.';const arenaHeader=document.querySelector('.arena-head');arenaHeader.children[0].textContent=(team?'TEAM':'COUNTRY')+' BATTLE';arenaHeader.children[1].textContent=inputMode==='gifts'?'NO GIFTS · OUT AFTER 2 TURNS':'FREE PLAY · COMMENT 1–4';document.querySelector('.queue-hint').textContent='Comment a waiting '+(team?'team':'country')+'’s number (5–14). Most requested enters next.';document.querySelector('.arena-caption').children[0].textContent='♛ TOP GIFTER IN EVERY FRAME';$('rosterMode').value=rosterMode;$('inputMode').value=inputMode}
let lastMotionId=null;
function animateMove(){const m=state.motion;if(!m||m.phase!=='move'||m.pawn<0||m.id===lastMotionId)return;lastMotionId=m.id;if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;const el=document.querySelector(`.pawn[data-team="${m.team}"][data-pawn="${m.pawn}"]`);if(!el?.animate)return;const cellAt=p=>p<52?route[(p+m.team*13)%52]:p<58?lanes[m.team][p-52]:[7,7];const end=cellAt(m.to),points=[];const cellSize=$('board').getBoundingClientRect().width/15;if(m.from<0){const home=[[2.5,2.5],[2.5,11.5],[11.5,11.5],[11.5,2.5]][m.team];points.push({transform:`translate(${(home[1]-end[1])*cellSize}px,${(home[0]-end[0])*cellSize}px) scale(1.15)`})}for(let p=Math.max(0,m.from);p<=m.to;p++){const c=cellAt(p);points.push({transform:`translate(${(c[1]-end[1])*cellSize}px,${(c[0]-end[0])*cellSize}px) scale(1.12)`})}points.push({transform:'translate(0,-3px) scale(1)'});el.animate(points,{duration:850,easing:'linear'});el.style.zIndex='12'}
renderRosterEditor();updateModeLabels();
